// Generated by AI (UnitTest MCP)
use std::cmp::Ordering;
use std::collections::HashSet;

use crate::{
    embed, ingest, now_unix, AgentFootprintOverlap, Direction, Edge, MindLeak, MindLeakError, Node,
    NodeType, Preflight, PreflightNode, RelationType, Result, ScoredNode, Subgraph, WeightedEdge,
    WriteOutcome,
};

/// Nodes embedded per `/v1/embeddings` request during the offline index pass.
const EMBED_BATCH: usize = 64;

/// Most-relevant impact nodes a pre-flight will carry.
///
/// The pre-flight is read before every edit, so its size is part of its cost.
/// Measured 2026-07-29 on `crates/lodestar-mcp/src/tools/mod.rs`, one path
/// returned 196 nodes over 295 edges — 351 KB — because `impact_radius`
/// traverses at zero minimum weight with no node cap, and Rust files had just
/// gained real cross-file structure. A mandatory decision aid that displaces
/// the decision fails the same way an unread one does.
///
/// Matches the hard cap on `working_set`, which bounds the same kind of view
/// for the same reason.
const PREFLIGHT_IMPACT_LIMIT: usize = 32;

impl MindLeak {
    /// Semantic recall: return nodes whose content is closest in meaning to
    /// `query`, via the optional local embedding index (ADR-0008). Complements
    /// FTS/graph search — seed the results into `multi_hop_query`. Errors
    /// cleanly when no embedding model is reachable.
    ///
    /// Returns nothing when nothing clears the similarity floor (ADR-0053).
    /// Before the floor existed this always answered, and the answer was often a
    /// stranger matched on one shared word — which the caller had no way to
    /// distinguish from a real hit. An empty result is the honest one.
    pub fn recall(&self, query: &str, limit: usize) -> Result<Vec<ScoredNode>> {
        let query_vec = self.embedder.embed(query)?;
        let hits = embed::recall(
            &self.store.conn,
            &query_vec,
            self.embedder.model(),
            limit,
            self.recall_floor as f32,
        )?;
        if hits.is_empty() {
            tracing::debug!(
                %query,
                floor = self.recall_floor,
                "recall found nothing above the similarity floor"
            );
        }
        let mut out = Vec::new();
        for (id, score) in hits {
            if let Some(node) = self.store.get_node(&id)? {
                out.push(ScoredNode {
                    node,
                    depth: 0,
                    score: score as f64,
                });
            }
        }
        Ok(out)
    }

    /// Populate the semantic embedding index for nodes missing a current vector
    /// (off the zero-token hot path). Embeds in batches so the pass costs one
    /// round trip per `EMBED_BATCH` nodes instead of one per node. Returns how
    /// many nodes were indexed.
    pub fn index_nodes(&self, limit: usize) -> Result<usize> {
        let now = now_unix();
        let pending =
            embed::nodes_missing_embeddings(&self.store.conn, self.embedder.model(), limit)?;
        let mut indexed = 0;
        for chunk in pending.chunks(EMBED_BATCH) {
            let texts: Vec<String> = chunk.iter().map(|(_, text)| text.clone()).collect();
            let vectors = self.embedder.embed_batch(&texts)?;
            for ((id, _), vector) in chunk.iter().zip(vectors) {
                embed::upsert(&self.store.conn, id, self.embedder.model(), &vector, now)?;
                indexed += 1;
            }
        }
        Ok(indexed)
    }

    // ---- agent-facing queries (MCP tool surface) ----------------------------

    /// Tool 1: navigate the graph up to `max_depth` hops from a seed node or
    /// search phrase, keeping only edges above `min_weight` effective weight.
    pub fn multi_hop_query(
        &self,
        seed_entity: &str,
        max_depth: u32,
        min_weight: f64,
    ) -> Result<Subgraph> {
        let now = now_unix();
        let seeds = self.store.resolve_seed(seed_entity, 3)?;
        if seeds.is_empty() {
            return Ok(Subgraph {
                seed: vec![],
                nodes: vec![],
                edges: vec![],
            });
        }
        self.store
            .traverse(&seeds, Direction::Outgoing, max_depth, min_weight, now)
    }

    /// Tool 2: what changes/breaks if `target_artifact` is modified — dependents,
    /// prior failing executions, and related intents. Agent observations are not
    /// dependency paths.
    pub fn impact_radius(&self, target_artifact: &str) -> Result<Subgraph> {
        let now = now_unix();
        let seeds = self.store.resolve_seed(target_artifact, 1)?;
        if seeds.is_empty() {
            return Err(MindLeakError::NotFound(target_artifact.to_string()));
        }
        self.store.impact_radius(&seeds, now)
    }

    /// The deterministic node ids a set of workspace paths and symbol ids
    /// resolves to, sorted and deduplicated.
    fn preflight_seeds(&self, paths: &[String], symbols: &[String]) -> Vec<String> {
        let mut node_ids = paths
            .iter()
            .map(|path| format!("artifact:{}", self.repo_relative(path)))
            .collect::<Vec<_>>();
        node_ids.extend(symbols.iter().cloned());
        node_ids.sort();
        node_ids.dedup();
        node_ids
    }

    /// Decay-aware pre-flight footprint for workspace paths and MindLeak symbol
    /// ids (ADR-0024). Other agents only; advisory, never a lock.
    pub fn check_overlap(
        &self,
        paths: &[String],
        symbols: &[String],
        exclude_agent: Option<&str>,
    ) -> Result<Vec<AgentFootprintOverlap>> {
        let node_ids = self.preflight_seeds(paths, symbols);
        self.store
            .agent_footprint_overlap(&node_ids, exclude_agent, now_unix())
    }

    /// The whole pre-flight question, answered in one call: who else is active
    /// on the paths about to be edited, and what this graph already knows about
    /// them — dependents, previously failing executions, and related intents
    /// (ADR-0066).
    ///
    /// This composes two capabilities that already existed and were already
    /// reachable. Both were separately reachable, and that was the defect:
    /// `get_impact_radius` was called three times in this repository's lifetime
    /// against 8,109 ingests, because learning a file's history of failure
    /// needed a second call at the moment attention had already moved on.
    /// Nothing here that depended on remembering has ever been adopted
    /// (ADR-0046 measured the same zero), so the answer now rides on the
    /// question agents already ask instead of waiting for one they do not.
    ///
    /// Deterministic and zero-token: every part is a graph read.
    pub fn preflight(
        &self,
        paths: &[String],
        symbols: &[String],
        exclude_agent: Option<&str>,
    ) -> Result<Preflight> {
        let now = now_unix();
        let requested = self.preflight_seeds(paths, symbols);
        let footprints = self
            .store
            .agent_footprint_overlap(&requested, exclude_agent, now)?;

        // Seed the impact traversal only from ids the graph actually holds, and
        // report the rest as unknown rather than letting them vanish into an
        // empty result that reads like "nothing depends on this".
        let mut known = Vec::new();
        let mut unknown = Vec::new();
        for id in &requested {
            if self.store.node_exists(id)? {
                known.push(id.clone());
            } else {
                unknown.push(id.clone());
            }
        }

        let impact = if known.is_empty() {
            Subgraph {
                seed: Vec::new(),
                nodes: Vec::new(),
                edges: Vec::new(),
            }
        } else {
            self.store.impact_radius(&known, now)?
        };
        let (impact, impact_edges, impact_total) = bound_impact(impact);

        Ok(Preflight {
            requested,
            unknown,
            footprints,
            impact,
            impact_edges,
            impact_total,
        })
    }

    /// Tool 3: record an explicit architectural decision as an intent node,
    /// linked to the nodes it affects.
    pub fn record_decision(
        &self,
        decision_text: &str,
        related_nodes: &[String],
    ) -> Result<(String, WriteOutcome)> {
        let now = now_unix();
        let mut outcome = WriteOutcome::default();
        let intent_id = format!("intent:{}", ingest::short_hash(decision_text));
        let label = ingest::clamp(decision_text, 80);
        let intent =
            Node::new(&intent_id, NodeType::Intent, label, now).with_content(decision_text);
        if self.store.upsert_node(&intent)? {
            outcome.nodes_created += 1;
        }
        outcome.node_ids.push(intent_id.clone());

        for target in related_nodes {
            if self.store.node_exists(target)? {
                let edge = Edge::new(&intent_id, target, RelationType::RelatesTo, now);
                if self.store.upsert_edge(&edge)? {
                    outcome.edges_created += 1;
                }
            }
        }
        // A conclusion that cannot be read back until someone remembers to run
        // `index_nodes` is not recorded, it is queued (ADR-0053). Embed it now.
        //
        // This does not breach the zero-token write path: this verb is already
        // the explicit, agent-supplied route, not deterministic `ingest_*`. When
        // no embedding server is reachable the node is still written, and the
        // fact that it is unembedded is reported rather than swallowed.
        outcome.embedded = self.embed_node_now(&intent_id, decision_text, now).is_ok();
        Ok((intent_id, outcome))
    }

    /// Embed one just-written node so it is immediately recallable (ADR-0053).
    fn embed_node_now(&self, id: &str, text: &str, now: i64) -> Result<()> {
        let vector = self.embedder.embed(text)?;
        embed::upsert(&self.store.conn, id, self.embedder.model(), &vector, now)?;
        Ok(())
    }

    pub fn record_decision_for_agent(
        &self,
        agent: &str,
        decision_text: &str,
        related_nodes: &[String],
    ) -> Result<(String, WriteOutcome)> {
        let result = self.record_decision(decision_text, related_nodes)?;
        self.observe(agent, &result.1.node_ids, now_unix())?;
        Ok(result)
    }
}

/// Reduce a full impact traversal to something a caller can read: the most
/// relevant nodes, without their content, and only the edges among them.
///
/// Ranking by score keeps the nodes the traversal considered closest rather
/// than whichever the database happened to return first, so the cut is
/// meaningful and not arbitrary. The untruncated total travels with it, because
/// a caller that cannot tell a complete answer from a trimmed one will read the
/// trimmed one as complete.
fn bound_impact(impact: Subgraph) -> (Vec<PreflightNode>, Vec<WeightedEdge>, usize) {
    let impact_total = impact.nodes.len();
    let mut ranked = impact.nodes;
    ranked.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(Ordering::Equal));
    ranked.truncate(PREFLIGHT_IMPACT_LIMIT);

    let kept: HashSet<String> = ranked.iter().map(|node| node.node.id.clone()).collect();
    let edges = impact
        .edges
        .into_iter()
        .filter(|edge| kept.contains(&edge.source_id) && kept.contains(&edge.target_id))
        .collect();

    let nodes = ranked
        .into_iter()
        .map(|scored| PreflightNode {
            id: scored.node.id,
            label: scored.node.label,
            node_type: scored.node.node_type,
            depth: scored.depth,
            score: scored.score,
        })
        .collect();

    (nodes, edges, impact_total)
}
